package com.farmdirect.controller;
import com.farmdirect.dao.OrderDAO;import com.farmdirect.model.User;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;
@WebServlet("/admin") public class AdminServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");if(u==null||!"ADMIN".equals(u.getRole())){p.sendRedirect("login.jsp");return;}try{q.setAttribute("orders",new OrderDAO().all());q.getRequestDispatcher("admin.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{User u=(User)q.getSession().getAttribute("user");if(u==null||!"ADMIN".equals(u.getRole())){p.sendRedirect("login.jsp");return;}try{new OrderDAO().status(Integer.parseInt(q.getParameter("id")),q.getParameter("status"));}catch(Exception ignored){}p.sendRedirect("admin");}}
